package org.apache.commons.math.stat.correlation;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.distribution.TDistribution;
import org.apache.commons.math.distribution.TDistributionImpl;
import org.apache.commons.math.linear.BlockRealMatrix;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.stat.regression.SimpleRegression;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.stat.correlation.PearsonsCorrelation;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class PearsonsCorrelation_getCorrelationPValues_TriageGen4Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetCorrelationPValues_PerfectCorrelation() {
        // Perfect correlation (r = 1.0)
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // Diagonal should be 0
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);

        // Off-diagonal for perfect correlation should be 0 (t approaches infinity)
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 0), EPSILON);
    }

    @Test
    public void testGetCorrelationPValues_StandardData() {
        // Data with known correlation
        double[][] data = {
            {1, 2, 3},
            {2, 4, 5},
            {3, 1, 2}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        int nVars = 3;
        // Check dimensions
        Assert.assertEquals(nVars, pValues.getRowDimension());
        Assert.assertEquals(nVars, pValues.getColumnDimension());

        // Check diagonal
        for (int i = 0; i < nVars; i++) {
            Assert.assertEquals(0.0, pValues.getEntry(i, i), EPSILON);
        }

        // Check symmetry: p(i,j) should equal p(j,i)
        Assert.assertEquals(pValues.getEntry(0, 1), pValues.getEntry(1, 0), EPSILON);
        Assert.assertEquals(pValues.getEntry(0, 2), pValues.getEntry(2, 0), EPSILON);
        Assert.assertEquals(pValues.getEntry(1, 2), pValues.getEntry(2, 1), EPSILON);

        // Check bounds: p-values must be between 0 and 1
        for (int i = 0; i < nVars; i++) {
            for (int j = 0; j < nVars; j++) {
                double val = pValues.getEntry(i, j);
                Assert.assertTrue(val >= 0.0 && val <= 1.0);
            }
        }
    }

    @Test
    public void testGetCorrelationPValues_NegativeCorrelation() {
        // Strong negative correlation
        double[][] data = {
            {1, 2, 3},
            {3, 2, 1}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // r = -1, t = abs(-1 * sqrt( (2)/(1-1) )) -> approaching infinity
        // p-value should be 0
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testGetCorrelationPValues_InsufficientObservations() {
        // nObs - 2 must be > 0 for T-Distribution. 
        // If nObs = 2, nObs - 2 = 0, which is invalid for TDistribution.
        double[][] data = {
            {1, 2},
            {3, 4}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        // This should throw an exception during TDistribution instantiation or calculation
        correlation.getCorrelationPValues();
    }

    @Test
    public void testGetCorrelationPValues_ZeroCorrelation() {
        // Data with zero correlation
        // Note: Hard to get exactly 0 with small datasets, but we can use orthogonal vectors
        double[][] data = {
            {1, 0, -1},
            {0, 1, 0},
            {-1, 0, 1}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // For r=0, t=0. cumulativeProbability(0) = 0.5. 2 * (1 - 0.5) = 1.0
        // Check if p-values are high for uncorrelated variables
        Assert.assertTrue(pValues.getEntry(0, 1) > 0.5);
    }
}
